-- 52 Model Railway: the controller. The riding is the engine's
-- (`path_follow`); this sets the train's speed on every car of it at once,
-- so they keep their spacing. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/52-model-railway.scene"
local PARTS = { "Engine", "Carriage1", "Carriage2", "Carriage3", "Carriage4" }
local captions = true
local speed, running, tilt = 120.0, true, true
local status

local function set_train(field, value)
    for _, name in ipairs(PARTS) do
        local e = Entity.find_by_name(name)
        if e then PathFollow.set(e, field, value) end
    end
end

function init(entity)
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Up") then speed = math.min(320, speed + 40); set_train("speed", speed) end
    if Input.is_key_just_pressed("Down") then speed = math.max(-200, speed - 40); set_train("speed", speed) end
    if Input.is_key_just_pressed("Space") then running = not running; set_train("playing", running) end
    if Input.is_key_just_pressed("T") then
        tilt = not tilt
        PostProcess.set_enabled("tilt_shift", tilt)
    end
    if status then
        local s = math.floor(speed + 0.5)
        UI.set_text(status, (running and ("train " .. s .. " a second") or "train stopped")
            .. (tilt and "" or "   tilt-shift off"))
    end
end
